b:if.script:
    //
    document.addEventListener("DOMContentLoaded", function() {
      // Share: Copy Link
      document.querySelectorAll(".copy-link-btn").forEach(function(btn) {
          btn.addEventListener("click", function() {
              let url = btn.getAttribute("data-url") || window.location.href;
              let status = btn.closest(".post-share-box") ? btn.closest(".post-share-box").querySelector(".share-copy-status") : null;
              if (navigator.clipboard && window.isSecureContext) {
                  navigator.clipboard.writeText(url).then(function() {
                      if(status) { status.style.display = "block"; setTimeout(function(){ status.style.display = "none"; }, 2200); }
                  });
              } else {
                  let temp = document.createElement("textarea");
                  temp.value = url; temp.style.position = "fixed"; temp.style.opacity = "0";
                  document.body.appendChild(temp); temp.select();
                  try { document.execCommand("copy"); } catch(e) {}
                  document.body.removeChild(temp);
                  if(status) { status.style.display = "block"; setTimeout(function(){ status.style.display = "none"; }, 2200); }
              }
          });
      });

      // Share: Encoded social actions
      document.querySelectorAll("[data-sia-share]").forEach(function(btn) {
          btn.addEventListener("click", function() {
              let network = btn.getAttribute("data-sia-share") || "";
              let title = btn.getAttribute("data-title") || document.title;
              let url = btn.getAttribute("data-url") || window.location.href;
              let image = btn.getAttribute("data-image") || "";
              let encodedTitle = encodeURIComponent(title);
              let encodedUrl = encodeURIComponent(url);
              let encodedImage = encodeURIComponent(image);
              let target = "";

              if(network === "whatsapp") target = "https://wa.me/?text=" + encodeURIComponent(title + " " + url);
              else if(network === "facebook") target = "https://www.facebook.com/sharer/sharer.php?u=" + encodedUrl;
              else if(network === "x") target = "https://twitter.com/intent/tweet?text=" + encodedTitle + "&url=" + encodedUrl;
              else if(network === "telegram") target = "https://t.me/share/url?url=" + encodedUrl + "&text=" + encodedTitle;
              else if(network === "linkedin") target = "https://www.linkedin.com/sharing/share-offsite/?url=" + encodedUrl;
              else if(network === "reddit") target = "https://www.reddit.com/submit?url=" + encodedUrl + "&title=" + encodedTitle;
              else if(network === "pinterest") target = "https://www.pinterest.com/pin/create/button/?url=" + encodedUrl + "&media=" + encodedImage + "&description=" + encodedTitle;
              else if(network === "email") {
                  window.location.href = "mailto:?subject=" + encodedTitle + "&body=" + encodedUrl;
                  return;
              }

              if(target) {
                  let opened = window.open(target, "_blank", "noopener,noreferrer");
                  if(opened) opened.opener = null;
              }
          });
      });

      // Share: Native Web Share
      document.querySelectorAll(".native-share-btn").forEach(function(btn) {
          if (!navigator.share) {
              btn.style.display = "none";
              return;
          }
          btn.addEventListener("click", function() {
              navigator.share({
                  title: btn.getAttribute("data-title") || document.title,
                  url: btn.getAttribute("data-url") || window.location.href
              }).catch(function() {});
          });
      });

      let postBody = document.getElementById("post-body-content");
      if(postBody) {
          let headings = postBody.querySelectorAll("h2, h3");
          if(headings.length >= 2) {
              let tocHTML = "<div class='toc-box'><div class='toc-title'>Table of Contents</div><ul>";
              headings.forEach((heading, index) => {
                  let id = "heading-toc-" + index;
                  heading.id = id;
                  tocHTML += "<li><a href='#" + id + "'>" + heading.innerText + "</a></li>";
              });
              tocHTML += "</ul></div>";
              headings[0].insertAdjacentHTML("beforebegin", tocHTML);
          }
      }

      // SIA Featured Image URL Dedupe
      function normalizeSiaImageUrl(value) {
          if(!value) return "";
          try {
              let raw = String(value).replace(/=w\d+(?:-h\d+)?(?:-[^/?#]+)?$/i, "");
              let u = new URL(raw, window.location.href);
              u.hash = "";
              u.search = "";
              u.pathname = u.pathname
                  .replace(/\/s\d+(?:-[^/]+)?\//i, "/")
                  .replace(/\/w\d+(?:-h\d+)?(?:-[^/]+)?\//i, "/");
              return (u.origin + u.pathname).replace(/\/+$/, "");
          } catch(e) {
              return String(value).split("?")[0].split("#")[0]
                  .replace(/\/s\d+(?:-[^/]+)?\//i, "/")
                  .replace(/\/w\d+(?:-h\d+)?(?:-[^/]+)?\//i, "/")
                  .replace(/=w\d+(?:-h\d+)?(?:-[^/?#]+)?$/i, "")
                  .replace(/\/+$/, "");
          }
      }

      let featuredImg = document.getElementById("sia-featured-image");
      let bodyImg = document.querySelector("#post-body-content img");
      if(featuredImg && bodyImg) {
          let featuredKey = normalizeSiaImageUrl(featuredImg.currentSrc || featuredImg.src);
          let bodyKey = normalizeSiaImageUrl(bodyImg.currentSrc || bodyImg.src);
          if(featuredKey && bodyKey && featuredKey === bodyKey) {
              let parentLink = bodyImg.parentElement;
              if(parentLink && parentLink.tagName === "A" && parentLink.children.length === 1 && !parentLink.textContent.trim()) {
                  parentLink.style.display = "none";
              } else {
                  bodyImg.style.display = "none";
              }
          }
      }

      let labelsNode = document.getElementById("post-labels-data");
      let labelsText = labelsNode ? labelsNode.innerText.trim() : "";
      if(labelsText !== "") {
          let primarySilo = labelsText.split(",")[0].trim();
          let relatedHeading = document.getElementById("silo-related-heading");
          if(relatedHeading) relatedHeading.textContent = "More From " + primarySilo;
      }

      fetch("/feeds/posts/default?alt=json&max-results=5")
      .then(res => res.json())
      .then(data => {
          let posts = data.feed.entry;
          if(!posts) return;
          let latestHtml = "";
          posts.forEach(post => {
              let link = post.link.find(l => l.rel === "alternate").href;
              let title = post.title.$t;
              latestHtml += "<li><a href='" + link + "'>" + title + "</a></li>";
          });
          document.getElementById("latest-posts-list").innerHTML = latestHtml;
      });
// 6. Auto Image Alt & Title Text (Advanced Image SEO)
      let postTitleElement = document.querySelector(".post-title");
      if(postTitleElement && postBody) {
          let pTitle = postTitleElement.innerText.trim();
          let allImages = postBody.querySelectorAll("img");
          let imgCount = 1;

          allImages.forEach(img => {
              if(!img.getAttribute("alt") || img.getAttribute("alt").trim() === "") {
                  let finalAltText = imgCount === 1 ? pTitle : pTitle + " - " + imgCount;
                  img.setAttribute("alt", finalAltText);
                  img.setAttribute("title", finalAltText);
                  imgCount++;
              }
          });
      }
    });
    //

//
window.SIA_CONFIG = window.SIA_CONFIG || {};
window.SIA_CONFIG.edgeManifestUrl = 'https://raw.githubusercontent.com/dilipnachna/SIA-Infinity-AI-Blogger-Template/main/public/sia-edge.json';
window.SIA_CONFIG.graphUrl = 'https://raw.githubusercontent.com/dilipnachna/SIA-Infinity-AI-Blogger-Template/main/public/graphs/' + window.location.hostname + '/sia-graph.json';
window.SIA_CONFIG.maxRelated = 6;
window.SIA_CONFIG.graphCacheMinutes = 30;
window.SIA_CONFIG.edgeManifestCacheMinutes = 60;
window.SIA_CONFIG.relatedTarget = 'related-posts-list';
window.SIA_CONFIG.statusTarget = 'sia-hybrid-status';
window.SIA_CONFIG.currentLabelsTarget = 'post-labels-data';

window.addEventListener('sia:hybrid-ready', function(event) {
  var detail = event && event.detail ? event.detail : {};
  var related = Array.isArray(detail.related) ? detail.related : [];
  if (!related.length) return;

  var body = document.getElementById('post-body-content');
  if (!body || body.querySelector('.sia-contextual-link')) return;
  var paragraphs = body.querySelectorAll('p');
  if (paragraphs.length < 2) return;

  var labels = document.getElementById('post-labels-data');
  var primarySilo = labels && labels.textContent
    ? labels.textContent.split(',')[0].trim()
    : 'Related';
  var item = related[0];

  var box = document.createElement('div');
  box.className = 'in-article-link sia-contextual-link';
  box.setAttribute('data-sia-mode', detail.mode || 'unknown');

  var prefix = document.createTextNode('More in ' + primarySilo + ': ');
  var link = document.createElement('a');
  link.href = item.url;
  link.textContent = item.title;
  if (item.score !== undefined) link.setAttribute('data-sia-score', item.score);
  if (item.reasons && item.reasons.length) link.setAttribute('data-sia-reasons', item.reasons.join(','));

  box.appendChild(prefix);
  box.appendChild(link);
  paragraphs[1].insertAdjacentElement('afterend', box);
});
